CREATE FUNCTION cmd_validate_broker_operation_receipt() RETURNS trigger LANGUAGE plpgsql AS $$ DECLARE task cmd_actor_task_receipt%ROWTYPE; op rule_broker_operation%ROWTYPE; expected_percent smallint; BEGIN SELECT * INTO STRICT op FROM rule_broker_operation WHERE rule_id=NEW.operation_rule_id AND operation_code=NEW.operation_code; SELECT * INTO STRICT task FROM cmd_actor_task_receipt WHERE command_id=NEW.task_command_id; IF task.actor_id<>NEW.actor_id OR task.skill_rule_id<>op.skill_rule_id OR task.difficulty_rule_id<>op.difficulty_rule_id OR task.base_time_frame_rule_id<>op.time_frame_rule_id OR task.check_total<>NEW.check_total OR task.effect<>NEW.effect OR task.succeeded<>NEW.succeeded THEN RAISE EXCEPTION 'Broker operation receipt does not match its task'; END IF; IF NEW.price_percent IS NOT NULL THEN SELECT CASE WHEN NEW.operation_code='determine-purchase-price' THEN purchase_percent ELSE sale_percent END INTO STRICT expected_percent FROM rule_modified_price_band WHERE (minimum_result IS NULL OR minimum_result<=NEW.check_total) AND (maximum_result IS NULL OR maximum_result>=NEW.check_total); IF expected_percent<>NEW.price_percent THEN RAISE EXCEPTION 'Broker price percent does not match modified price table'; END IF; END IF; RETURN NEW; END $$;
CREATE CONSTRAINT TRIGGER cmd_broker_operation_receipt_valid AFTER INSERT ON cmd_broker_operation_receipt DEFERRABLE INITIALLY DEFERRED FOR EACH ROW EXECUTE FUNCTION cmd_validate_broker_operation_receipt();
CREATE FUNCTION cmd_validate_carousing_influence_receipt() RETURNS trigger LANGUAGE plpgsql AS $$ DECLARE i enc_influence_attempt%ROWTYPE; expected_skill bigint; BEGIN SELECT skill_rule_id INTO STRICT expected_skill FROM rule_carousing_influence_mechanic; SELECT * INTO STRICT i FROM enc_influence_attempt WHERE command_id=NEW.influence_command_id; IF NEW.skill_rule_id<>expected_skill OR i.acting_actor_id<>NEW.actor_id OR i.target_actor_id<>NEW.target_actor_id OR i.skill_modifier<>NEW.skill_modifier OR i.characteristic_modifier<>NEW.characteristic_modifier THEN RAISE EXCEPTION 'Carousing receipt does not match influence attempt'; END IF; RETURN NEW; END $$;
CREATE CONSTRAINT TRIGGER cmd_carousing_influence_receipt_valid AFTER INSERT ON cmd_carousing_influence_receipt DEFERRABLE INITIALLY DEFERRED FOR EACH ROW EXECUTE FUNCTION cmd_validate_carousing_influence_receipt();
